// Check the current folder name against known folder names to set the
// correct default color, if needed.
if (window.arguments[0].serverType == "rss") {
  gDefaultColor = folderColors.RSS;
} else {
  const flags = gMsgFolder.flags;
  for (const [key, value] of Object.entries(folderColors)) {
    if (flags & key) {
      gDefaultColor = value;
      break;
    }
  }
}

const colorInput = document.getElementById("color");
const storedColor = FolderTreeProperties.getColor(gMsgFolder.URI);
colorInput.value = storedColor || gDefaultColor;
isDefaultColor = !storedColor;
colorInput.addEventListener("input", () => {
  isDefaultColor = false;
  // Preview the chosen color.
  Services.obs.notifyObservers(
    gMsgFolder,
    "folder-color-preview",
    colorInput.value
  );
});
const resetColorButton = document.getElementById("resetColor");
resetColorButton.addEventListener("click", function () {
  colorInput.value = gDefaultColor;
  // Preview the default color.
  isDefaultColor = true;
  Services.obs.notifyObservers(
    gMsgFolder,
    "folder-color-preview",
    gDefaultColor
  );
